mapper.select:
/* 매핑 한 행 */

 WHERE AI_ROUT_MPNG_SN = #{aiRoutMpngSn}
   AND DEL_YN = 'N'

mapper.update:
/* 매핑 수정 */
UPDATE AI_ROUT_MPNG
   SET DOMN_NM       = #{route.domnNm}
     , TRGT_SCRN_NM  = #{route.trgtScrnNm}
     , SCRN_ID       = #{route.scrnId}
     , SCRN_PARAM_CN = #{route.scrnParamCn}
     , INST_KWRD_CN  = #{route.instKwrdCn}
     , MVMN_MTHD_CD  = #{route.mvmnMthdCd}
     , RPRS_CHIP_YN  = #{route.rprsChipYn}
     , RMRK_CN       = #{route.rmrkCn}
     , USE_YN        = #{route.useYn}
     , MDFR_ID       = #{actorId}
 WHERE AI_ROUT_MPNG_SN = #{route.aiRoutMpngSn}
   AND DEL_YN = 'N'

/* 우선순위 변경 */
UPDATE AI_ROUT_MPNG
   SET PRRT_SEQ = #{prrtSeq}
     , MDFR_ID  = #{actorId}
 WHERE AI_ROUT_MPNG_SN = #{aiRoutMpngSn}
   AND DEL_YN = 'N'

/* 매핑 삭제 */
UPDATE AI_ROUT_MPNG
   SET DEL_YN  = 'Y'
     , MDFR_ID = #{actorId}
 WHERE AI_ROUT_MPNG_SN = #{aiRoutMpngSn}
   AND DEL_YN = 'N'
